import { settleTheme } from "../helpers/theme-preferences";
import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";
import AxeBuilder from "@axe-core/playwright";

test("appearance: first document paint uses verified saved palette", async ({
  page,
  themeUser,
}) => {
  // Keep hydration from masking an incorrect head-script palette.
  await page.route("**/_next/static/**/*.js", (route) => route.abort());
  await page.goto("/privacy", { waitUntil: "domcontentloaded" });
  const root = page.locator("html");
  for (const [mode, color] of [
    ["light", "#fafafa"],
    ["dark", "#0a0a0a"],
  ]) {
    await page.evaluate((theme) => {
      localStorage.setItem("mailloop-appearance", "vercel");
      localStorage.setItem("mailloop-theme", theme);
    }, mode);
    await page.goto("/compose", { waitUntil: "domcontentloaded" });
    await expect(root).toHaveAttribute("data-appearance", "vercel");
    await expect(root).toHaveAttribute("data-theme", mode);
    await expect(page.locator('meta[name="theme-color"]')).toHaveAttribute(
      "content",
      color,
    );
  }
  await setThemePlan(themeUser, "FREE");
  await page.reload({ waitUntil: "domcontentloaded" });
  await expect(root).toHaveAttribute("data-appearance", "purple");
  await expect(root).toHaveAttribute("data-theme", "dark");
});

test("appearance: four previews, default, persistence, keyboard and landing isolation", async ({
  page,
  context,
}, testInfo) => {
  await page.emulateMedia({ colorScheme: "light", reducedMotion: "reduce" });
  await page.goto("/privacy");
  const root = page.locator("html");
  const trigger = page.getByRole("button", { name: "Choose appearance" });
  await expect(root).toHaveAttribute("data-theme", "dark");
  await expect(root).toHaveAttribute("data-appearance", "purple");
  await expect(
    page.getByRole("button", { name: "Switch to light theme", exact: true }),
  ).toHaveCount(0);
  await trigger.click();
  await expect(page.getByRole("menuitemradio")).toHaveCount(4);
  await expect(
    page.getByRole("menuitemradio", {
      name: "Nightbloom Dark",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("ArrowDown");
  await expect(
    page.getByRole("menuitemradio", {
      name: "Obsidian Dark",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("ArrowUp");
  await expect(
    page.getByRole("menuitemradio", {
      name: "Nightbloom Dark",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("ArrowLeft");
  await expect(
    page.getByRole("menuitemradio", {
      name: "Lavender Light",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("ArrowRight");
  await expect(
    page.getByRole("menuitemradio", {
      name: "Nightbloom Dark",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("Home");
  await expect(
    page.getByRole("menuitemradio", {
      name: "Lavender Light",
      exact: true,
    }),
  ).toBeFocused();
  await page.keyboard.press("End");
  await page.keyboard.press("Enter");
  await expect(trigger).toBeFocused();
  await expect(root).toHaveAttribute("data-appearance", "vercel");
  await expect(root).toHaveAttribute("data-theme", "dark");
  const menu = page.getByRole("menu", { name: "Appearance", exact: true });
  let previewColors: string[] | undefined;
  for (const [label, appearance, theme] of [
    ["Lavender Light", "purple", "light"],
    ["Nightbloom Dark", "purple", "dark"],
    ["Chalk Light", "vercel", "light"],
    ["Obsidian Dark", "vercel", "dark"],
  ]) {
    await trigger.click();
    await page.getByRole("menuitemradio", { name: label, exact: true }).click();
    await expect(root).toHaveAttribute("data-appearance", appearance);
    await expect(root).toHaveAttribute("data-theme", theme);
    await expect(trigger).toHaveAttribute(
      "title",
      `Theme: ${label.split(" ")[0]} (${label.substring(label.indexOf(" ") + 1)})`,
    );
    await trigger.click();
    const selected = page.getByRole("menuitemradio", {
      name: label,
      exact: true,
    });
    await expect(selected).toBeFocused();
    await expect(selected).toHaveAttribute("aria-checked", "true");
    await expect(selected).toHaveCSS("border-width", "2px");
    await expect(selected).toHaveCSS("border-radius", "16px");
    await page.keyboard.press("ArrowRight");
    await page.keyboard.press("ArrowLeft");
    await expect(selected).toBeFocused();
    await expect(selected).toHaveCSS("outline-style", "solid");
    await expect(menu).toHaveCSS("border-radius", "20px");
    await expect(
      menu.getByText("Pick the mood for your workspace."),
    ).toBeVisible();
    const colors = await page
      .locator(".appearance-preview")
      .evaluateAll((previews) =>
        previews.map((preview) => getComputedStyle(preview).backgroundColor),
      );
    if (previewColors) expect(colors).toEqual(previewColors);
    previewColors = colors;
    const bounds = (await menu.boundingBox())!;
    expect(bounds.x).toBeGreaterThanOrEqual(16);
    expect(bounds.x + bounds.width).toBeLessThanOrEqual(
      page.viewportSize()!.width - 16,
    );
    expect(bounds.y + bounds.height).toBeLessThanOrEqual(
      page.viewportSize()!.height - 16,
    );
    if (testInfo.project.name === "desktop") expect(bounds.width).toBe(440);
    const cards = await page.getByRole("menuitemradio").all();
    for (const card of cards) {
      await settleTheme(page);
      const cardBounds = (await card.boundingBox())!;
      const previewBounds = (await card
        .locator(".appearance-preview")
        .boundingBox())!;
      expect(previewBounds.x).toBeGreaterThan(cardBounds.x);
      expect(previewBounds.x + previewBounds.width).toBeLessThan(
        cardBounds.x + cardBounds.width,
      );
      const pillBounds = (await card
        .locator(".appearance-preview-card > b")
        .boundingBox())!;
      expect(pillBounds.y + pillBounds.height).toBeLessThan(
        previewBounds.y + previewBounds.height,
      );
    }
    const first = (await cards[0].boundingBox())!;
    const second = (await cards[1].boundingBox())!;
    expect(first.y).toBe(second.y);
    expect(second.x).toBeGreaterThan(first.x + first.width);
    await page.screenshot({
      path: testInfo.outputPath(`theme-picker-${appearance}-${theme}.png`),
    });
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    await page.keyboard.press("Escape");
  }
  await page.reload();
  await expect(root).toHaveAttribute("data-appearance", "vercel");
  await expect(root).toHaveAttribute("data-theme", "dark");
  await trigger.click();
  await page.screenshot({ path: testInfo.outputPath("theme-picker.png") });
  const bounds = (await menu.boundingBox())!;
  expect(bounds.x).toBeGreaterThanOrEqual(0);
  expect(bounds.x + bounds.width).toBeLessThanOrEqual(
    page.viewportSize()!.width,
  );
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
  await page.keyboard.press(" ");
  await expect(menu).toHaveCount(0);
  await expect(trigger).toBeFocused();
  await trigger.click();
  await page.mouse.click(1, 1);
  await expect(menu).toHaveCount(0);
  const other = await context.newPage();
  await other.goto("/terms");
  await other.getByRole("button", { name: "Choose appearance" }).click();
  await other
    .getByRole("menuitemradio", {
      name: "Lavender Light",
      exact: true,
    })
    .click();
  await expect(root).toHaveAttribute("data-appearance", "purple");
  await expect(root).toHaveAttribute("data-theme", "light");
  await other.close();
  await page
    .getByRole("navigation", { name: "Policy navigation" })
    .getByRole("link", { name: "Pricing", exact: true })
    .click();
  await expect(page).toHaveURL(/\/pricing$/);
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(
    "Simple pricing for serious outreach.",
  );
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", { name: "Obsidian Dark", exact: true })
    .click();
  await expect(page.locator(".pricing-page")).toHaveCSS(
    "background-color",
    "rgb(10, 10, 10)",
  );
  await expect(root).toHaveAttribute("data-themed", "");
  await context.clearCookies();
  await page.goto("/");
  await expect(page.locator(".landing")).toBeVisible();
  await expect(root).not.toHaveAttribute("data-themed", "");
  await expect(
    page.getByRole("button", { name: "Choose appearance" }),
  ).toHaveCount(0);
  await expect(
    page.getByRole("button", { name: "Switch to light theme", exact: true }),
  ).toBeVisible();
});

test("appearance: blocked storage keeps a selection while navigating", async ({
  page,
}) => {
  await page.addInitScript(() => {
    Storage.prototype.getItem = () => {
      throw new Error("Storage blocked");
    };
    Storage.prototype.setItem = () => {
      throw new Error("Storage blocked");
    };
  });
  await page.goto("/privacy");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
    .click();
  await page
    .getByRole("link", { name: "Terms of Service", exact: true })
    .click();
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    "vercel",
  );
  await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
});

test("appearance: blocked writes override a previously saved choice for the current document", async ({
  page,
}) => {
  await page.addInitScript(() => {
    localStorage.setItem("mailloop-appearance", "purple");
    localStorage.setItem("mailloop-theme", "dark");
    Storage.prototype.setItem = () => {
      throw new Error("Writes blocked");
    };
  });
  await page.goto("/privacy");
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
    .click();
  await page
    .getByRole("link", { name: "Terms of Service", exact: true })
    .click();
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    "vercel",
  );
  await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
});

test("appearance: cards retain geometry in the workspace and scroll on short screens", async ({
  page,
}, testInfo) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/privacy");
  const trigger = page.getByRole("button", { name: "Choose appearance" });
  await trigger.click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
    .click();
  // Exercise the shared workspace CSS without requiring an authenticated account.
  await page
    .locator("html")
    .evaluate((root) => root.setAttribute("data-workspace", ""));
  await trigger.click();
  const card = page.getByRole("menuitemradio", {
    name: "Chalk Light",
    exact: true,
  });
  await expect(card).toHaveCSS("border-radius", "16px");
  await expect(card).toHaveCSS("border-width", "2px");
  await expect(card).toHaveCSS("color", "rgb(23, 23, 23)");
  await page.keyboard.press("Escape");
  await page.setViewportSize({ width: 320, height: 300 });
  await trigger.click();
  const menu = page.getByRole("menu");
  const bounds = (await menu.boundingBox())!;
  expect(bounds.x).toBe(16);
  expect(bounds.x + bounds.width).toBe(304);
  expect(bounds.y + bounds.height).toBeLessThanOrEqual(284);
  expect(
    await menu.evaluate(
      (element) => element.scrollHeight > element.clientHeight,
    ),
  ).toBe(true);
  await page.keyboard.press("End");
  const last = page.getByRole("menuitemradio", {
    name: "Obsidian Dark",
    exact: true,
  });
  await expect(last).toBeFocused();
  await expect(last).toBeInViewport();
  await page.screenshot({
    path: testInfo.outputPath("theme-picker-short-screen.png"),
  });
  await page.keyboard.press("Enter");
  await expect(trigger).toBeFocused();
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
});

for (const reducedMotion of ["no-preference", "reduce"] as const) {
  test(`appearance: picker and palette motion (${reducedMotion})`, async ({
    page,
  }) => {
    await page.emulateMedia({ reducedMotion });
    await page.addInitScript(() => {
      const start = document.startViewTransition.bind(document);
      document.startViewTransition = (...args) => {
        document.documentElement.dataset.transitionCount = String(
          Number(document.documentElement.dataset.transitionCount ?? 0) + 1,
        );
        return start(...args);
      };
    });
    await page.goto("/privacy");
    const root = page.locator("html");
    const trigger = page.getByRole("button", { name: "Choose appearance" });
    await trigger.click();
    const menu = page.getByRole("menu", { name: "Appearance", exact: true });
    await expect(menu).toHaveCSS(
      "animation-name",
      reducedMotion === "reduce" ? "none" : "appearance-menu-enter",
    );
    await page
      .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
      .click();
    await expect(root).toHaveAttribute("data-appearance", "vercel");
    await expect(root).toHaveAttribute("data-theme", "light");
    await expect(trigger).toBeFocused();
    if (reducedMotion === "no-preference") {
      await expect(root).toHaveAttribute("data-transition-count", "1");
      await expect(root).not.toHaveAttribute("data-appearance-transition");
      await expect
        .poll(() => page.evaluate(() => document.getAnimations().length))
        .toBe(0);
    } else {
      await expect(root).not.toHaveAttribute("data-transition-count");
      await expect(root).not.toHaveAttribute("data-appearance-transition");
    }
    // Re-selecting the same palette should not start another transition.
    await trigger.click();
    await page
      .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
      .click();
    if (reducedMotion === "no-preference") {
      await expect(root).toHaveAttribute("data-transition-count", "1");
    }
  });
}

for (const mode of ["light", "dark"] as const) {
  test(`appearance: Free locks saved and cross-tab black preferences (${mode})`, async ({
    page,
    context,
    themeUser,
  }) => {
    await setThemePlan(themeUser, "FREE");
    await page.addInitScript((mode) => {
      localStorage.setItem("mailloop-appearance", "vercel");
      localStorage.setItem("mailloop-theme", mode);
    }, mode);
    await page.goto("/pricing");
    const root = page.locator("html");
    await expect(root).toHaveAttribute("data-appearance", "purple");
    await expect(root).toHaveAttribute("data-theme", mode);
    await page.getByRole("button", { name: "Choose appearance" }).click();
    const black = page.getByRole("menuitemradio", { name: /Chalk/ });
    await expect(black).not.toHaveAttribute("aria-disabled", "true");
    await expect(page.locator(".appearance-lock").first()).toHaveCSS(
      "color",
      mode === "light" ? "rgb(109, 40, 217)" : "rgb(196, 181, 253)",
    );
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    await black.hover();
    await expect(page.getByRole("tooltip")).toHaveText(
      "Upgrade to Premium to unlock this theme",
    );
    await black.focus();
    await expect(page.getByRole("tooltip")).toBeVisible();
    await page.keyboard.press("Enter");
    const upgradeDialog = page.getByRole("dialog", {
      name: "Upgrade to Premium",
      exact: true,
    });
    await expect(upgradeDialog).toBeVisible();
    await upgradeDialog.getByRole("button", { name: /^Upgrade for / }).click();
    await expect(page).toHaveURL(/\/usage$/);
    await expect(root).toHaveAttribute("data-appearance", "purple");
    await page.getByRole("button", { name: "Choose appearance" }).click();
    const upgrade = page.getByRole("menuitem", {
      name: "Upgrade to Premium",
      exact: true,
    });
    await expect(upgrade).toHaveAttribute("href", "/usage");
    await page.keyboard.press("Escape");
    const other = await context.newPage();
    await other.goto("/privacy");
    await other.evaluate(() => {
      localStorage.setItem("mailloop-appearance", "purple");
      localStorage.setItem("mailloop-appearance", "vercel");
    });
    await expect(root).toHaveAttribute("data-appearance", "purple");
    await other.close();
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page
      .getByRole("menu", { name: "Appearance", exact: true })
      .getByRole("menuitem", { name: "Upgrade to Premium" })
      .click();
    await expect(page).toHaveURL(/\/usage$/);
    await page.goto("/pricing");
    await context.clearCookies();
    await page.reload();
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await expect(black).not.toHaveAttribute("aria-disabled", "true");
    await expect(root).toHaveAttribute("data-appearance", "purple");
    expect(
      await page.evaluate(() => localStorage.getItem("mailloop-appearance")),
    ).toBe("vercel");
  });
  test(`appearance: expiry falls back and upgrade restores saved black (${mode})`, async ({
    page,
    themeUser,
  }) => {
    await page.addInitScript((mode) => {
      localStorage.setItem("mailloop-appearance", "vercel");
      localStorage.setItem("mailloop-theme", mode);
    }, mode);
    await page.goto("/pricing");
    const root = page.locator("html");
    await expect(root).toHaveAttribute("data-appearance", "vercel");
    await setThemePlan(themeUser, "PAID", new Date(Date.now() + 6000));
    await page.reload();
    await expect(root).toHaveAttribute("data-appearance", "vercel");
    await expect(root).toHaveAttribute("data-appearance", "purple", {
      timeout: 15000,
    });
    await expect(root).toHaveAttribute("data-theme", mode);
    expect(
      await page.evaluate(() => localStorage.getItem("mailloop-appearance")),
    ).toBe("vercel");
    await setThemePlan(themeUser, "PAID");
    await page.evaluate(() =>
      window.dispatchEvent(new Event("mailloop:access-refresh")),
    );
    await expect(root).toHaveAttribute("data-appearance", "vercel");
  });
}

for (const gated of [true, false]) {
  test(`appearance: workspace refresh updates Premium access with quota gating ${gated}`, async ({
    page,
    themeUser,
  }) => {
    await setThemeQuotaGating(gated);
    try {
      await page.addInitScript(() => {
        localStorage.setItem("mailloop-appearance", "vercel");
        localStorage.setItem("mailloop-theme", "light");
      });
      await page.goto("/usage");
      await expect(
        page.getByRole("heading", { name: "Usage", exact: true }),
      ).toBeVisible({ timeout: 15000 });
      const root = page.locator("html");
      await expect(root).toHaveAttribute("data-appearance", "vercel");
      // The heading is server rendered; interact before dispatching the event
      // so the workspace refresh listener has mounted.
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await page.keyboard.press("Escape");
      await setThemePlan(themeUser, "FREE");
      await Promise.all([
        page.waitForResponse(
          (response) => response.url().endsWith("/api/quota") && response.ok(),
        ),
        page.evaluate(() =>
          window.dispatchEvent(new Event("mailloop:access-refresh")),
        ),
      ]);
      await expect(root).toHaveAttribute("data-appearance", "purple");
      await expect(root).toHaveAttribute("data-theme", "light");
      expect(
        await page.evaluate(() => localStorage.getItem("mailloop-appearance")),
      ).toBe("vercel");
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await expect(
        page.getByRole("menuitemradio", { name: /Chalk/ }),
      ).not.toHaveAttribute("aria-disabled", "true");
      await page.keyboard.press("Escape");
      await setThemePlan(themeUser, "PAID");
      await Promise.all([
        page.waitForResponse(
          (response) => response.url().endsWith("/api/quota") && response.ok(),
        ),
        page.evaluate(() =>
          window.dispatchEvent(new Event("mailloop:access-refresh")),
        ),
      ]);
      await expect(root).toHaveAttribute("data-appearance", "vercel");
    } finally {
      await setThemeQuotaGating(false);
    }
  });
}

test("appearance: locked theme hint sits below the card", async ({
  page,
  themeUser,
}, info) => {
  await setThemePlan(themeUser, "FREE");
  await page.setViewportSize({ width: 1000, height: 1000 });
  await page.goto("/privacy");
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await settleTheme(page);
  const card = page.getByRole("menuitemradio", { name: /Obsidian/ });
  await card.hover();
  const hint = page.getByRole("tooltip");
  await expect(hint).toHaveText("Upgrade to Premium to unlock this theme");
  await settleTheme(page);
  const cardBounds = (await card.boundingBox())!;
  await expect
    .poll(async () => (await hint.boundingBox())?.y ?? 0)
    .toBeGreaterThan(cardBounds.y + cardBounds.height);
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
  await page.screenshot({ path: info.outputPath("locked-theme-hint.png") });
});
